WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Treatment regimen"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%renal cell%' AND LOWER("Treatment regimen") LIKE '%ici%' AND LOWER("Treatment regimen") LIKE '%tki%'
)
SELECT * FROM base;
